import type { ExampleSentence, LexicalEntry } from '../../types/card';
import type { ScriptId } from '../../types/language';
import type { LanguageCode } from '../../types/language';
import ja from './ja.json';
import ko from './ko.json';
import vi from './vi.json';
import zh from './zh.json';

/**
 * The vocabulary, by exam level.
 *
 * Generated by `tools/vocab/build.mjs` from published word lists — HSK's own,
 * the community JLPT reconstructions, the NIKL/TOPIK lists, and a Vietnamese
 * frequency list — and committed, so a clone studies without touching the
 * network and a change to a syllabus arrives as a reviewable diff. Sources and
 * licences are in `docs/DATA.md`.
 *
 * Each language is one file keyed by level id, and the records inside use short
 * keys. That is not premature: this ships to a phone, and at eleven thousand
 * entries the difference between `frequencyRank` and `q` is a hundred kilobytes
 * of bundle carrying no information. They are expanded on the way out, once, and
 * cached — which is why `getLevelEntries` is the only way in.
 */

/** The on-disk record. Short keys; see the note above. */
interface CompactEntry {
  i: string;
  t: string;
  r: string;
  m: string[];
  /** Tones, per syllable. */
  o?: number[];
  /** Frequency rank; lower is more common. */
  q?: number;
  p?: string;
  c?: string[];
  /** Script variants, as [script, form] pairs. */
  v?: [string, string][];
  g?: string[];
  e?: ExampleSentence[];
  n?: string;
}

type LevelMap = Record<string, CompactEntry[]>;

const DATA: Record<LanguageCode, LevelMap> = {
  zh: zh as LevelMap,
  ja: ja as LevelMap,
  ko: ko as LevelMap,
  vi: vi as LevelMap,
};

/** Which language a level belongs to, worked out once from the data itself. */
const LANGUAGE_OF_LEVEL = new Map<string, LanguageCode>();
for (const [code, levels] of Object.entries(DATA) as [LanguageCode, LevelMap][]) {
  for (const levelId of Object.keys(levels)) LANGUAGE_OF_LEVEL.set(levelId, code);
}

const expanded = new Map<string, LexicalEntry[]>();

/**
 * Every word in a level, most common first.
 *
 * Memoised per level rather than per language: a learner studying HSK 2 pays for
 * two levels, not for all nine.
 */
export function getLevelEntries(levelId: string): LexicalEntry[] {
  const cached = expanded.get(levelId);
  if (cached) return cached;

  const code = LANGUAGE_OF_LEVEL.get(levelId);
  const records = code ? (DATA[code][levelId] ?? []) : [];
  const entries = records.map((record) => expand(record, code!, levelId));

  expanded.set(levelId, entries);
  return entries;
}

/** Every word this app ships for a language, across all of its levels. */
export function getVocabularyEntries(code: LanguageCode): LexicalEntry[] {
  return Object.keys(DATA[code]).flatMap((levelId) => getLevelEntries(levelId));
}

/** How many words each level holds, for the settings and progress screens. */
export function getLevelSizes(code: LanguageCode): Record<string, number> {
  return Object.fromEntries(
    Object.entries(DATA[code]).map(([levelId, entries]) => [levelId, entries.length]),
  );
}

export function getVocabularyCounts(): Record<LanguageCode, number> {
  return {
    zh: countFor('zh'),
    ja: countFor('ja'),
    ko: countFor('ko'),
    vi: countFor('vi'),
  };
}

function countFor(code: LanguageCode): number {
  return Object.values(DATA[code]).reduce((total, entries) => total + entries.length, 0);
}

function expand(record: CompactEntry, code: LanguageCode, levelId: string): LexicalEntry {
  return {
    id: record.i,
    languageCode: code,
    target: record.t,
    reading: record.r,
    meanings: record.m,
    levelIds: [levelId],
    examples: record.e ?? [],
    tags: record.g ?? [],
    ...(record.o ? { tones: record.o } : {}),
    ...(record.q !== undefined ? { frequencyRank: record.q } : {}),
    ...(record.p ? { partOfSpeech: record.p } : {}),
    ...(record.c ? { components: record.c } : {}),
    ...(record.n ? { mnemonic: record.n } : {}),
    ...(record.v
      ? { variants: record.v.map(([script, form]) => ({ script: script as ScriptId, form })) }
      : {}),
  };
}

/**
 * Where each language's words came from.
 *
 * Shown in the app rather than only in a document: two of these licences require
 * attribution, and a learner is entitled to know whether the list they are being
 * graded against is an examining body's or somebody's best reconstruction.
 */
export const VOCABULARY_SOURCES: Record<LanguageCode, { name: string; url: string; licence: string; official: boolean }> = {
  zh: {
    name: 'Complete HSK Vocabulary',
    url: 'https://github.com/drkameleon/complete-hsk-vocabulary',
    licence: 'MIT',
    official: true,
  },
  ja: {
    name: 'Open Anki JLPT Decks',
    url: 'https://github.com/jamsinclair/open-anki-jlpt-decks',
    licence: 'MIT',
    official: false,
  },
  ko: {
    name: 'NIKL / TOPIK lists, glossed from Wiktionary',
    url: 'https://github.com/julienshim/combined_korean_vocabulary_list',
    licence: 'MIT, glosses CC BY-SA 4.0',
    official: false,
  },
  vi: {
    name: 'OpenSubtitles frequency list, glossed from Wiktionary',
    url: 'https://github.com/hermitdave/FrequencyWords',
    licence: 'CC BY-SA 4.0',
    official: false,
  },
};
